import React, { useState } from "react";
import all_product from "../Assets/all_product"; // Adjust your path accordingly
import "./Product.css"; // Create this CSS file for styling

const ProductList = () => {
  const [searchTerm, setSearchTerm] = useState("");

  // Filter products by search term (name or category)
  const filteredProducts = all_product.filter((product) =>
    product.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    product.category.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="product-page-container">
      <header className="product-header">
        <h1>CampusMarket Products</h1>
        <p>Explore exclusive deals from fellow students</p>
        <input
          type="text"
          placeholder="Search products or categories..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          className="search-input"
        />
      </header>

      <main className="product-grid">
        {filteredProducts.length === 0 ? (
          <p className="no-results">No products found.</p>
        ) : (
          filteredProducts.map((product) => (
            <div key={product.id} className="product-card">
              <img
                src={product.image}
                alt={product.name}
                className="product-image"
              />
              <div className="product-info">
                <h3>{product.name}</h3>
                <p className="category">Category: {product.category}</p>
                <p className="price">
                  ${product.new_price.toFixed(2)}{" "}
                  {product.old_price && (
                    <span className="old-price">
                      ${product.old_price.toFixed(2)}
                    </span>
                  )}
                </p>
                <button className="btn-primary">View Details</button>
              </div>
            </div>
          ))
        )}
      </main>
    </div>
  );
};

export default ProductList;
